from lib import *
S = SS('g56')
steps = [
    step("同一份 heap profile 换 -sample_index 看。程序:garbageX 分配约 100 MB 的 1 KiB 切片但全部丢弃,retainY 分配并保留 50 个 1 MiB,retainZ 保留 16 万个 64 字节对象,最后 runtime.GC() 后写 profile(MemProfileRate 默认 512 KiB)。inuse_space(总计 60.87MB):retainY 46.26MB、retainZ 12.10MB,前 6 项里没有 garbageX。alloc_space(总计 174.92MB):garbageX 98.10MB、retainY 46.26MB、retainZ 28.06MB。", t=tl(S(1)), done=lidx(S(1), 'main.retainY', 'main.retainZ'), mark=lidx(S(1), 'main.garbageX', 'Type: alloc_space'), b=bars([['inuse:retainY (MB)', 46.26, '46.26'], ['inuse:garbageX', 0, '前6项无'], ['alloc:garbageX', 98.10, '98.10'], ['alloc:retainZ', 28.06, '28.06']], 98.1, done=[0], mark=[2, 3]), kv=KV([['inuse_space', '还活着的:retainY 46.26、retainZ 12.10 MB'], ['alloc_space', '累计分配:garbageX 98.10 MB 排第一'], ['含义', '找内存泄漏看 inuse,找分配热点看 alloc']], ['含义'])),
    step("heap profile 是最近一次 GC 时的快照:先 GC,再分配并保留 50 MiB 的 retainY,不再 GC 直接写 profile,retainY 的 inuse_space = 20133 kB;再调用 runtime.GC() 后写,retainY = 54477 kB。(第一次不是 0,因为分配 50 MiB 的过程中堆增长触发过几次 GC,profile 反映的是其中最后一次完成时的状态。)", t=tl(S(2)), done=lidx(S(2), 'runtime.GC() 之后再写'), mark=lidx(S(2), '不再 GC 直接写'), b=bars([['不再 GC:retainY (kB)', 20133, '20133'], ['GC 之后:retainY', 54477, '54477']], 54477, mark=[0], done=[1]), kv=KV([['不再 GC', 'retainY = 20133 kB'], ['再 GC 后', 'retainY = 54477 kB'], ['要点', '想看到刚分配的内存,先 runtime.GC()']], ['要点'])),
    step("采样率对估计精度的影响(retainZ 的统计里还包括 keepZ 切片自身的底层数组;MemProfileRate=1 时每次分配都被记录,当作基准 14200 kB)。每个采样率各跑 6 次:4096:最小 13936 / 中位 14119 / 最大 14464 kB;524288(默认):12394 / 16490 / 18538 kB;16777216:49152 / 83015 / 98304 kB。", t=tl(S(3)), done=lidx(S(3), 'MemProfileRate=        1:', 'MemProfileRate=     4096:'), mark=lidx(S(3), 'MemProfileRate=   524288:', 'MemProfileRate= 16777216:'), b=bars([['rate=1:基准 (kB)', 14200, '14200'], ['rate=4096 中位', 14119, '14119'], ['rate=512K 中位', 16490, '16490'], ['rate=16M 中位', 83015, '83015']], 83015, done=[0, 1], mark=[2, 3]), kv=KV([['rate=1', '14200 kB(逐个记录)'], ['rate=4096', '13936–14464 kB'], ['默认 512K', '12394–18538 kB'], ['rate=16M', '49152–98304 kB,基本不可用']], ['rate=16M'])),
    step("采样率对分配速度的影响(分配 64 字节,testing.Benchmark):MemProfileRate=0:11 ns/次;默认 524288:10 ns/次;4096:17 ns/次;1:512 ns/次。", t=tl(S(4)), mark=lidx(S(4), 'MemProfileRate=1 ', 'MemProfileRate=4096'), done=lidx(S(4), 'MemProfileRate=0 ', 'MemProfileRate=524288'), b=bars([['rate=0 (ns)', 11, '11'], ['默认 512K', 10, '10'], ['rate=4096', 17, '17'], ['rate=1', 512, '512']], 512, done=[0, 1], mark=[2, 3]), kv=KV([['rate=0 / 默认', '11 / 10 ns'], ['rate=4096', '17 ns'], ['rate=1', '512 ns,约 50 倍']], ['rate=1'])),
    step("文档原文:pprof.go 写着 heap profile 报告的是最近一次完成的垃圾回收时的统计,省略更近的分配,以免让 profile 偏向垃圾而不是存活数据;没有任何 GC 时则报告所有已知分配。mprof.go 的 MemProfileRate:平均每 MemProfileRate 字节分配采样一次;设为 1 则包含每个分配块,设为 0 则完全关闭;处理工具假定采样率在程序生命期内不变,所以要在 main 开头只改一次。", t=tl(S(5)), done=lidx(S(5), 'most recently completed', 'to avoid skewing', 'one allocation per MemProfileRate'), mark=lidx(S(5), 'set MemProfileRate to 1', 'set MemProfileRate to 0', 'at the beginning of main', 'var MemProfileRate'), kv=KV([['快照时刻', '最近一次完成的 GC'], ['默认采样率', '512 * 1024'], ['修改时机', 'main 开头,只改一次']], ['修改时机'])),
]
A = mkartg('g56', 56, 'Go,pprof,heap profile,inuse,alloc,MemProfileRate,真实验证,动画演示',
    '在 Go 1.27.1 里实测 heap profile:同一份 profile 里,丢弃的 98 MB 垃圾只在 alloc_space 里出现、不在 inuse_space 前列;刚分配的内存不GC就看不全(20133 kB 对 54477 kB);采样率从默认 512 KiB 提高到 4096 字节,小对象估计的波动从 12394–18538 kB 缩到 13936–14464 kB,而 MemProfileRate=1 让每次 64 字节分配从 10 ns 涨到 512 ns。',
    'heap profile 有 inuse 和 alloc 两种视角,内存泄漏和分配热点要看不同的列;它还是按采样得到的估计值,而且只反映最近一次 GC 时的状态。这篇用一个已知的程序验证这几点,并量采样率的精度与代价。',
    [('98.10 MB', 'garbageX 在 alloc_space 里的占比最大,但它不在 inuse_space 的前列'), ('20133 vs 54477 kB', '不 GC 与 GC 之后再写 profile,retainY 的 inuse_space'), ('10 → 512 ns', '分配 64 字节在默认采样率与 MemProfileRate=1 下的耗时')],
    [('inuse 和 alloc', '<p><code>inuse_space</code> 只算还活着的,<code>alloc_space</code> 算累计分配。丢弃的 98 MB 垃圾在后者里排第一、在前者里不出现。排查泄漏看 inuse,排查 GC 压力看 alloc。</p>'),
     ('profile 是 GC 时的快照', '<p>文档说 heap profile 报告最近一次完成的 GC 时的统计。实测分配 50 MiB 后不 GC 直接写,只看到 20133 kB(分配过程中触发过 GC,所以不是 0);再调用 <code>runtime.GC()</code> 后是 54477 kB。线上用 <code>/debug/pprof/heap</code> 取样时也要记得这点。</p>'),
     ('估计值,不是精确值', '<p>默认每 512 KiB 采样一次,所以结果是估计:真实保留的 50 MiB,在第一次运行里读到 46.26 MB,在另一次运行里读到 54477 kB,小对象的波动更大。采样率 4096 时 6 次都在 13936–14464 kB,默认值是 12394–18538 kB,而 16 MiB 的采样率直接得到 49152–98304 kB——基本不可用。</p>'),
     ('精度的代价', '<p>MemProfileRate=1 让每次 64 字节分配从 10 ns 涨到 512 ns,约 50 倍;4096 只涨到 17 ns。想要更准的数字又不想拖慢程序,可以用中间值,但要在 <code>main</code> 开头设置、且只设一次(文档要求)。</p>'),
     ('读文档的要点', '<p>文档里的两处关键约束:profile 反映最近一次 GC;采样率必须在程序生命周期内保持不变。这两条都在本文的实验里得到了印证,但我没有测在运行中途改变采样率会导致什么错误结果。</p>')],
    steps,
    [ENV_G + '。小对象实验里 retainZ 包含 keepZ 切片本身的底层数组(每个 []byte 头 24 字节),所以基准值是 14200 kB 而不是 10000 kB;MemProfileRate=1 的结果当作基准;每个采样率各运行 6 次(进程重启);分配耗时用 testing.Benchmark,单次测量;读过的源码:runtime/pprof/pprof.go 的 heap profile 说明,runtime/mprof.go 的 MemProfileRate',
     '没有验证:Linux 上的结果、go tool pprof 网页界面、allocs profile 与 heap profile 的区别细节、运行中途修改采样率的后果、inuse_objects 与 alloc_objects 的对照、真实服务中 /debug/pprof/heap 的开销'],
    'heap profile')
